use core::fmt::Write;

use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance, ItemVerdict};

struct Node;

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must read",
        Importance::WorthALook => "worth a look",
        Importance::Skip => "skip",
    }
}

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_rank(i: Importance) -> u8 {
    match i {
        Importance::MustRead => 0,
        Importance::WorthALook => 1,
        Importance::Skip => 2,
    }
}

fn render(date: &str, overview: &str, entries: &[ItemVerdict]) -> String {
    let mut msg = String::new();
    let _ = writeln!(msg, "Digest for {}", date);

    let overview = overview.trim();
    if !overview.is_empty() {
        let _ = writeln!(msg);
        let _ = writeln!(msg, "{}", overview);
    }

    let mut ordered: Vec<&ItemVerdict> = entries.iter().collect();
    ordered.sort_by_key(|e| importance_rank(e.importance));

    if ordered.is_empty() {
        let _ = writeln!(msg);
        let _ = writeln!(msg, "No items made the digest today.");
    } else {
        for e in ordered {
            let _ = writeln!(msg);
            let _ = writeln!(
                msg,
                "[{} / {}] {}",
                importance_label(e.importance),
                category_label(e.category),
                e.title.trim()
            );
            if !e.feed.trim().is_empty() {
                let _ = writeln!(msg, "  from: {}", e.feed.trim());
            }
            if !e.link.trim().is_empty() {
                let _ = writeln!(msg, "  {}", e.link.trim());
            }
            let summary = e.summary.trim();
            if !summary.is_empty() {
                let _ = writeln!(msg, "  {}", summary);
            }
        }
    }

    msg
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(&composed.date, &composed.overview, &composed.entries);
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
